/**
 * 负责隐狼原刀继承查询和刷新，输入为原槽、真实 World 与晚阵营 source。
 * 原角色检查后才查阵营，再核继承状态与存活真狼；无 World 不增加查询或授刀。
 * 持久继承来自实际提交，不改真实阵营，也不从拟议死亡授予权限。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { getHiddenWolfState, recordHiddenWolfKnifeInheritance } from "./state";

/** 当前刀权与已获得的历史继承分别查询；数据标记本身不能恢复权限。 */
export function canHiddenWolfKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  if (
    !world ||
    role.role !== Role.HiddenWolf ||
    currentCamp()?.camp !== Camp.Wolf ||
    getHiddenWolfState(role)?.hasInheritedKnife !== true
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}

/** 仅开局装配或实际死亡 owner 提交此变化；先写标记，发表失败不回退。 */
export function refreshHiddenWolfInheritance(world: World, events: GameEvent[], day: number): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!;
  const state = role.role === Role.HiddenWolf ? getHiddenWolfState(role) : undefined;
  if (!state || state.hasInheritedKnife) return;
  recordHiddenWolfKnifeInheritance(state);
  events.push({ timestamp: Date.now(), type: "hidden_wolf_awakened", payload: { actorId, day } });
}

/**
 * 负责机械狼当前刀继承资格与原继承事实；输入为实际存活名单、原槽和晚阵营 source。
 * 状态先按原点查询，再核角色／阵营／模式；无 World 时仍保守拒刀，不建立 Role 反向索引。
 * 刷新不改复制技能或真实阵营；先写继承再发表，后续错误保留已写前缀。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { hasCurrentMechanicalKillMode } from "./night_scope";
import { getMechanicalState, mechanicalKnifeSelected, recordMechanicalInheritance } from "./state";

export interface MechanicalInheritanceFact {
  readonly actorId: EntityId;
  readonly day: number;
  readonly firstKnifeNight: number;
}

/** 只读资格保持保守分支，不创建继承，也不恢复已失效的本夜模式。 */
export function canMechanicalKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  const state = getMechanicalState(role);
  if (
    !world ||
    role.role !== Role.MechanicalWolf ||
    currentCamp()?.camp !== Camp.Wolf ||
    !state ||
    !mechanicalKnifeSelected(state, state.mode?.day ?? 0) ||
    !hasCurrentMechanicalKillMode(world, role)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}

/** 仅装配或死亡 owner 提交完整实际死亡后调用；事实副本不授当前刀权。 */
export function refreshMechanicalInheritance(
  world: World,
  day: number,
  events?: GameEvent[],
): MechanicalInheritanceFact[] {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return [];
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!;
  if (role.role !== Role.MechanicalWolf) return [];
  const state = getMechanicalState(role);
  if (!state || !recordMechanicalInheritance(state, day)) return [];
  const fact = { actorId, day, firstKnifeNight: state.firstKnifeNight! };
  events?.push({ timestamp: Date.now(), type: "mechanical_awakened", payload: fact });
  return [fact];
}

/**
 * 负责觉醒隐狼的原刀继承资格与持久事实，按实际存活阵营名单查询，不从死亡提案发刀。
 * 输入保 World／日期、原槽和晚阵营 source；在原角色检查后才查阵营，不反向查找 Role 所属 World。
 * 槽与本夜权限仍由原 owner 复验；刷新只写继承记录，随后事实失败不回退已写前缀。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { currentAwakenedNight } from "./night_scope";
import { awakenedKnifeReady, getAwakenedState, recordAwakenedInheritance } from "./state";

export function canAwakenedKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  const state = getAwakenedState(role),
    night = world && currentAwakenedNight(world, role);
  if (
    !world ||
    role.role !== Role.AwakenedHiddenWolf ||
    currentCamp()?.camp !== Camp.Wolf ||
    !state ||
    night == null ||
    !awakenedKnifeReady(state, night)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}
/** 仅开局装配和实际死亡提交后刷新持久继承；不把查询或拟议死亡当作提交。 */
export function refreshAwakenedInheritance(world: World, day: number, events: GameEvent[]): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!,
    state = getAwakenedState(role);
  if (role.role !== Role.AwakenedHiddenWolf || !state || !recordAwakenedInheritance(state, day))
    return;
  events.push({
    timestamp: Date.now(),
    type: "awakened_inherited",
    payload: { actorId, day, firstKnifeNight: state.firstKnifeNight! },
  });
}

/**
 * 负责石像鬼原刀权继承查询与继承状态／事实刷新；输入为原角色、World、事件和明确日次。
 * 查询依原顺序核角色、继承标记、本夜查验完成回执，再核当前存活真狼名单；输出只是原刀权资格。
 * 刷新先写继承标记，后发表觉醒事实，发表失败不退标记；本模块不改角色或从未提交死亡推断继承。
 * 查验完成通过轻公开记账端口晚读，不能以公开函数或合法状态形状重新授权旧请求。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { getGargoyleState, recordGargoyleKnifeInheritance } from "./state";
import { completedGargoyleInspection } from "../role_inspection/night-commit-ports";

export function canGargoyleKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  if (
    !world ||
    role.role !== Role.Gargoyle ||
    currentCamp()?.camp !== Camp.Wolf ||
    getGargoyleState(role)?.hasInheritedKnife !== true ||
    !completedGargoyleInspection(world, role)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}
export function refreshGargoyleInheritance(world: World, events: GameEvent[], day: number): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!,
    state = role.role === Role.Gargoyle ? getGargoyleState(role) : undefined;
  if (!state || state.hasInheritedKnife) return;
  recordGargoyleKnifeInheritance(state);
  events.push({ timestamp: Date.now(), type: "gargoyle_awakened", payload: { actorId, day } });
}

/**
 * 定义纯白查验目标与对应工具校验。输入为当前 World 角色和请求目标；输出为政策允许
 * 的编号或结构化拒绝。目标枚举不提交查验或发表私密结果，原目标／来源及失败顺序不变。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Phase, Role, type EntityId } from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { World } from "../../../../core/domain/world";
import type { ToolRule } from "../../validation/contracts";
import type { RoleProfile } from "../contracts";
import { activeNightAbility } from "../abilities";

export function pureWhiteInspectionTargets(
  world: World,
  actorId: EntityId,
  policy: "pure_white" | "wolf_witch",
): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) =>
        id !== actorId &&
        (policy === "pure_white" || world.getComponent(id, COMPONENT.Camp)?.camp !== Camp.Wolf),
    );
}
export const PURE_WHITE_INSPECTION_TOOL: NonNullable<RoleProfile["toolSpecs"]>[number] = {
  name: "inspect_night_identity",
  parameters: {
    type: "object",
    properties: {
      target_id: { type: ["integer", "null"], minimum: 1 },
      abstain: { type: "boolean" },
    },
    required: ["target_id", "abstain"],
    additionalProperties: false,
  },
  argHint: 'inspect_night_identity args: {"target_id":number|null,"abstain":boolean}',
  userPromptHintKey: "action.inspect_night_identity.hint",
};
export const validatePureWhiteInspection: ToolRule = ({
  world,
  actorId,
  role,
  day,
  phase,
  abilityId,
  toolCall,
}) => {
  const ability = activeNightAbility(role, "role_check", day ?? 1, abilityId);
  if (!ability) return { code: RuleError.RoleInspectUnavailable };
  const policy = roleInspectionPolicy(ability.state);
  if (policy !== "pure_white" && policy !== "wolf_witch")
    return { code: RuleError.RoleInspectUnavailable };
  const expected = policy === "pure_white" ? Role.PureWhiteGirl : Role.WolfWitch;
  if (
    role.role !== expected ||
    ability.source.kind !== "native" ||
    ability.source.role !== expected
  )
    return { code: RuleError.RoleInspectUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name !== "inspect_night_identity") return { code: RuleError.ToolMismatch };
  const { target_id, abstain } = toolCall.args;
  if (abstain === true && target_id === null) return null;
  if (
    abstain !== false ||
    target_id === null ||
    !Number.isSafeInteger(target_id) ||
    !pureWhiteInspectionTargets(world, actorId, policy).includes(target_id)
  )
    return { code: RuleError.RoleInspectTarget };
  return null;
};

/**
 * 负责丘比特城市胜利贡献，输入保原情侣记录与存活名单，输出为原关系／阵营决策。
 * 真实当前 Camp 仅在原阵营点读取，历史 pairCamps 仍保捕获含义；不改情侣或标死玩家。
 */
import {
  COMPONENT,
  Camp,
  type World,
  type RoleComponent,
  type WinDecision,
} from "../../../../core/domain";
import { victoryDecision } from "../../win_conditions/results";
import { loversRecord, livingOriginalLovers } from "./relation";
/** 有限 City 板贡献只在完整死亡链之后判断，不把局部死亡提案当最终名单。 */
export function cupidCityDecision(world: World): { decision: WinDecision | null } | null {
  const record = loversRecord(world);
  if (!record) return null;
  const group = new Set<number>(record.pairIds);
  const follows = record.policy === "netease_2017_cupid_follows_lovers_v1";
  if (follows) group.add(record.actorId);
  const alive = world.getAliveEntityIds();
  if (record.mixed && livingOriginalLovers(world) && alive.every((id) => group.has(id)))
    return {
      decision: victoryDecision(
        world,
        { kind: "relationship", groupId: record.groupId },
        "cupid_lovers_only_survivors",
      ),
    };
  let wolves = 0,
    good = 0;
  for (const id of alive) {
    const role = world.getComponent(id, COMPONENT.Role);
    if (world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf) wolves++;
    if (
      world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Good &&
      !(follows && id === record.actorId && (record.mixed || record.pairCamps[0] === Camp.Wolf))
    )
      good++;
  }
  return {
    decision:
      wolves === 0
        ? victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated")
        : good === 0
          ? victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated")
          : null,
  };
}

/**
 * 负责在原预定发言之前开启辩论机会，并通过本族权威结算公开发言、密封投票和处罚。
 * 输入为当前日次、原参与者、请求构造端口、Provider 与网关；输出辩论事实及是否跳过原发言。
 * Provider 等待之后仍复验原体、生命、库存与警徽；请求构造不授权行动，付款和关闭保持本族原顺序。
 * 本窗口不发布局部匿名票统计；最后复验后同步提交结果、生命绑定处罚和需要的警徽移交。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type BadgeComponent,
  type VotingRightComponent,
} from "../../../../core/domain";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { commitSheriffBadgeChoice, badgeSuccessorEligible } from "../../sheriff/badge";
import { getDebaterState, consumeDebaterChallenge, recordDebaterChoice } from "./state";
import {
  openDebate,
  closeDebate,
  hasDebateCommit,
  commitDebate,
  blockDebateVote,
  nextDebateId,
  hasActiveDebate,
  type DebateAuthority,
} from "./authority";
import {
  captureOriginalParticipant as captureDebateParticipant,
  sameOriginalParticipant as sameDebateParticipant,
} from "../../../../core/domain/original-participant";
/** 有限 AWA 适配：原一次预定发言之前依次进行两次公开陈述，再收集密封匿名票。 */
export class DebaterWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    targetId: number,
    day: number,
    isCurrent: () => boolean,
  ): Promise<{ skipSpeech: boolean }> {
    if (hasActiveDebate(this.world)) throw new Error("debate_window_reentry");
    const empty = { skipSpeech: false };
    if (!isCurrent()) return empty;
    const actorId = this.world.getEntityIdsByRole(Role.Debater).find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role),
        state = getDebaterState(role);
      return (
        id !== targetId &&
        this.world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Good &&
        this.world.getAliveEntityIds().includes(id) &&
        state?.remaining === 1 &&
        state.choice === null &&
        !hasDebateCommit(this.world, id)
      );
    });
    if (actorId === undefined) return empty;
    let participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      ),
      actor = participants.get(actorId),
      target = participants.get(targetId);
    if (!actor || !target) return empty;
    const state = getDebaterState(actor.role)!,
      policy = state.policy;
    if (policy !== "awa_melbourne_2026_speech_gap_v1") return empty;
    const badgeSnapshot = (id: number) => {
      const badge = this.world.getComponent(id, COMPONENT.Badge),
        vote = this.world.getComponent(id, COMPONENT.VotingRight);
      return {
        id,
        badge,
        vote,
        isSheriff: badge?.isSheriff,
        destroyed: badge?.destroyed,
        weight: badge?.voteWeight,
        handoff: badge?.handoffPolicy,
        canVote: vote?.canVote,
        voteWeight: vote?.weight,
      };
    };
    const badges = [badgeSnapshot(actorId), badgeSnapshot(targetId)];
    const sameBadges = () =>
      badges.every(
        (b) =>
          this.world.getComponent(b.id, COMPONENT.Badge) === b.badge &&
          this.world.getComponent(b.id, COMPONENT.VotingRight) === b.vote &&
          b.badge?.isSheriff === b.isSheriff &&
          b.badge?.destroyed === b.destroyed &&
          b.badge?.voteWeight === b.weight &&
          b.badge?.handoffPolicy === b.handoff &&
          b.vote?.canVote === b.canVote &&
          b.vote?.weight === b.voteWeight,
      );
    const authority: DebateAuthority = {
      id: nextDebateId(this.world, day, actorId, targetId),
      day,
      actorId,
      targetId,
      stage: "challenge",
      participants,
    };
    // accepted 仅在两字段写完后置真；choice 保原对象身份，供等待后的状态复验。
    let accepted = false,
      choice: typeof state.choice = null;
    const current = () =>
      isCurrent() &&
      sameDebateParticipant(this.world, actor) &&
      sameDebateParticipant(this.world, target) &&
      getDebaterState(actor.role) === state &&
      state.policy === policy &&
      state.remaining === (accepted ? 0 : 1) &&
      state.choice === choice &&
      (choice === null || (choice.day === day && choice.targetId === targetId)) &&
      hasDebateCommit(this.world, actorId) === accepted &&
      sameBadges();
    const extras = {
      debate_id: authority.id,
      debate_actor_id: actorId,
      debate_target_id: targetId,
      allow_fallback: false,
    };
    const canceled = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "debate_canceled",
          payload: { actorId, targetId, day, reason: "scope_changed" },
        });
      return empty;
    };
    openDebate(this.world, authority);
    try {
      const request = requests.create({
        actorId,
        phase: Phase.Day,
        allowedTools: ["challenge"],
        stage: "debate_challenge",
        requiresAction: false,
        summary: { key: "request.summary.debate_challenge", parameters: { target: targetId } },
        context: extras,
      });
      if (!current()) return empty;
      const action = await provider.getAction(request);
      if (!current() || action?.name !== "challenge") return empty;
      const checked = this.gateway.validateAndSanitize(this.world, actorId, action, {
        phase: Phase.Day,
        day,
        debateId: authority.id,
      });
      if (!checked.ok || !current()) return empty;
      participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      );
      authority.participants = participants;
      // 提交账本先于库存；局部 choice 在保存槽之前创建，setter 失败时不回滚这些前缀。
      commitDebate(this.world, actorId);
      consumeDebaterChallenge(state);
      choice = { day, targetId };
      recordDebaterChoice(state, choice);
      accepted = true;
      this.events.push(
        { timestamp: Date.now(), type: "debater_revealed", payload: { actorId, day } },
        { timestamp: Date.now(), type: "debate_started", payload: { actorId, targetId, day } },
      );
      authority.stage = "speech";
      for (const speaker of [actorId, targetId]) {
        if (!current()) return canceled();
        const speechRequest = requests.create({
          actorId: speaker,
          phase: Phase.Day,
          allowedTools: ["speak"],
          stage: "debate_speech",
          requiresAction: true,
          summary: { key: "request.summary.debate_speech" },
          context: extras,
        });
        if (!current()) return canceled();
        const speech = await provider.getAction(speechRequest);
        if (!current()) return canceled();
        if (speech?.name !== "speak") continue;
        const valid = this.gateway.validateAndSanitize(this.world, speaker, speech, {
          phase: Phase.Day,
          day,
        });
        if (!current()) return canceled();
        if (valid.ok && valid.sanitizedCall?.name === "speak")
          this.events.push({
            timestamp: Date.now(),
            type: "debate_speech",
            payload: { actorId: speaker, text: valid.sanitizedCall.args.text },
          });
      }
      authority.stage = "ballot";
      // 调用任何 Provider 之前构造完整票轮；中间统计或单人票不会提前发布。
      const ballotRequests = [...participants.keys()].map((voterId) => ({
        voterId,
        request: requests.create({
          actorId: voterId,
          phase: Phase.Day,
          allowedTools: ["debate_vote"],
          stage: "debate_ballot",
          requiresAction: true,
          summary: { key: "request.summary.debate_ballot" },
          context: extras,
        }),
      }));
      if (!current()) return canceled();
      const replies = await Promise.all(
        ballotRequests.map(async ({ voterId, request }) => ({
          voterId,
          call:
            current() && sameDebateParticipant(this.world, participants.get(voterId)!)
              ? await provider.getAction(request)
              : null,
        })),
      );
      if (!current()) return canceled();
      const ballots = replies.map(({ voterId, call }) => {
        const p = participants.get(voterId)!;
        if (!sameDebateParticipant(this.world, p) || call?.name !== "debate_vote")
          return { voterId, support: null };
        const checked = this.gateway.validateAndSanitize(this.world, voterId, call, {
          phase: Phase.Day,
          day,
          debateId: authority.id,
        });
        return {
          voterId,
          support:
            checked.ok &&
            checked.sanitizedCall?.name === "debate_vote" &&
            sameDebateParticipant(this.world, p)
              ? checked.sanitizedCall.args.support
              : null,
        };
      });
      if (!current()) return canceled();
      // 已收票再次逐人复验，另一位玩家的校验可能撤销其原体资格。
      for (const ballot of ballots)
        if (!sameDebateParticipant(this.world, participants.get(ballot.voterId)!))
          ballot.support = null;
      const eligibleCount = participants.size,
        supports = ballots.filter((b) => b.support === true).length,
        rejects = ballots.filter((b) => b.support === false).length,
        abstentions = eligibleCount - supports - rejects,
        success = supports > eligibleCount / 2,
        blockedId = success ? targetId : actorId;
      const targetBadge = this.world.getComponent(targetId, COMPONENT.Badge),
        needsBadge = success && targetBadge?.isSheriff === true && !targetBadge.destroyed;
      if (needsBadge && !badgeSuccessorEligible(this.world, targetId, actorId)) return canceled();
      if (!current()) return canceled();
      // 最后复验之后同步提交结果、绑定原生命的处罚以及需要的警徽移交。
      if (needsBadge)
        commitSheriffBadgeChoice(this.world, targetId, "debate", this.events, actorId);
      blockDebateVote(this.world, blockedId, actorId, day);
      this.events.push(
        {
          timestamp: Date.now(),
          type: "debate_ballots_recorded",
          payload: { actorId, targetId, day, eligibleCount, ballots },
        },
        {
          timestamp: Date.now(),
          type: "debate_resolved",
          payload: {
            actorId,
            targetId,
            day,
            eligibleCount,
            supports,
            rejects,
            abstentions,
            success,
            blockedId,
          },
        },
      );
      return { skipSpeech: success };
    } finally {
      closeDebate(this.world, authority);
    }
  }
}

/**
 * 负责骑士白天决斗的完整选择窗口。输入为板子、原 World、请求构造端口、Provider、网关与提交回调；
 * 输出为原选择和是否结束白天，不在本窗口付款、标死或判胜。
 * 捕获演员和目标的存活组件、生命版本及角色／阵营字段，等待后按原顺序复验同一身体和库存。
 * 多骑士并发请求按编号尝试；网关预检两侧均复验，只有有效候选才要求提交回调。
 * 读取、Provider、网关及提交异常原样传播；已写前缀不回滚，缺少回调和明确 rejected 保留原分支。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  Role,
  Phase,
  KnightDuelWindow as DuelWindow,
  type Camp,
  type ActionProvider,
  type KnightDuelSelection,
  type KnightDuelCommit,
} from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { getKnightState } from "./state";

/** 本次窗口保留原组件引用与当时字段值；不是可序列化玩家资料，也不授予资源或死亡写权。 */
interface DuelParticipantSnapshot {
  // 生命版本记录活跃身体的变化；仅将 alive 改回 true 不恢复旧选择。
  life: AliveComponent;
  version: ReturnType<typeof aliveLifeVersion>;
  role: RoleComponent;
  // 角色保原引用，阵营在原值点晚查；同值 Camp 组件替换仍保持这个值快照，不加引用撤权。
  roleId: Role;
  camp: Camp | undefined;
}

/** 决斗收集保留原提交等待点；真实付款、事实和死亡提案仍归回调与后续经理结算。 */
export class KnightDuelWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: DuelWindow,
    isCurrent: () => boolean,
    commit?: (choice: KnightDuelSelection) => Promise<KnightDuelCommit>,
  ): Promise<{ selection: KnightDuelSelection | null; endsDay: boolean }> {
    // 原空结果在本次调用内共用；先查当前窗口，再按原配置或默认发言后机会筛选。
    const empty = { selection: null, endsDay: false };
    if (
      !isCurrent() ||
      !(config.knight?.enabledWindows ?? [DuelWindow.AfterSpeeches]).includes(window)
    )
      return empty;
    if (
      !this.world.getAliveEntityIds().some((id) => {
        const role = this.world.getComponent(id, COMPONENT.Role);
        return role?.role === Role.Knight && getKnightState(role)?.canDuel === true;
      })
    )
      return empty;
    // 先确认存在可决斗骑士，再完整捕获存活名单；不提前缓存配置、角色或库存。
    const snapshots = new Map<number, DuelParticipantSnapshot>(
      this.world.getAliveEntityIds().map((id) => {
        const life = this.world.getComponent(id, COMPONENT.Alive)!,
          role = this.world.getComponent(id, COMPONENT.Role)!;
        return [
          id,
          { life, version: aliveLifeVersion(life), role, roleId: role?.role, camp: this.world.getComponent(id, COMPONENT.Camp)?.camp },
        ] as const;
      }),
    );
    // 每个演员在请求前读取同一库存，Promise.all 保持快照名单顺序，不以响应先后提交。
    const picks = await Promise.all(
      [...snapshots].map(async ([actorId, actor]) => {
        const state = actor.role?.role === Role.Knight ? getKnightState(actor.role) : undefined;
        if (state?.canDuel !== true) return null;
        const action = await provider.getAction(
          requests.create({
            phase: Phase.Day,
            actorId,
            allowedTools: ["duel"],
            stage: window,
            requiresAction: false,
            summary: { key: "request.summary.knight_duel" },
            context: { duel_window: window },
          }),
        );
        if (action?.name !== "duel") return null;
        return { actorId, actor, state, action, target: snapshots.get(action.args.target_id) };
      }),
    );
    // 原生命、组件、角色及阵营字段都需匹配；此查询不消费库存，也不修改捕获对象。
    const sameLife = (id: number, snapshot: DuelParticipantSnapshot) =>
      this.world.getComponent(id, COMPONENT.Alive) === snapshot.life &&
      snapshot.life.alive &&
      snapshot.version !== undefined &&
      aliveLifeVersion(snapshot.life) === snapshot.version &&
      this.world.getComponent(id, COMPONENT.Role) === snapshot.role &&
      snapshot.role?.role === snapshot.roleId &&
      this.world.getComponent(id, COMPONENT.Camp)?.camp === snapshot.camp;
    for (const pick of picks
      .filter((item): item is NonNullable<typeof item> => item !== null)
      .sort((a, b) => a.actorId - b.actorId)) {
      // 按编号排序后的每次尝试，均在网关前后复验阶段、同一库存和目标生命。
      const valid = () =>
        isCurrent() &&
        sameLife(pick.actorId, pick.actor) &&
        getKnightState(pick.actor.role) === pick.state &&
        pick.state.canDuel &&
        pick.target !== undefined &&
        sameLife(pick.action.args.target_id, pick.target);
      if (
        !valid() ||
        !this.gateway.validateAndSanitize(this.world, pick.actorId, pick.action, {
          phase: Phase.Day,
          duelWindow: window,
          allowKnightDuel: true,
        }).ok ||
        !valid()
      )
        continue;
      // 缺回调只在有效候选处报原错误；rejected 继续下一项，提交抛错不回滚已有写入。
      if (!commit) throw new Error("knight_duel_commit_missing");
      const selection = { actorId: pick.actorId, targetId: pick.action.args.target_id },
        outcome = await commit(selection);
      if (outcome === "rejected") continue;
      return { selection, endsDay: outcome === "night" || outcome === "terminal" };
    }
    return empty;
  }
}

/**
 * 负责查验目标原体捕获与狐狸查验提案提交；输入保目标生命／Role引用和来源当前性。
 * 阵营晚查当前值，同值 Camp 替换不加引用撤权；输出保原记账与延期提案，知识发表不标死。
 * 原已付 owner／目标谓词不消费行动墓碑，不因剩余资源已经消费而取消提案。
 */
import { COMPONENT, Role, Camp, type RoleComponent, type World } from "../../../../core/domain";
import { livingNightLife, type NightLifeScope } from "../../../../core/domain/night_effects";
import type { NightStageState } from "../../stages/night/contracts";
const committed = new WeakMap<World, Set<number>>();
export function hasFoxInspectionNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
/** 等待前捕获原引用和值；新角色／生命不能取得旧待提交查验。 */
export function captureInspectionIdentity(world: World, target: NightLifeScope) {
  const role = world.getComponent(target.id, COMPONENT.Role);
  const kind = role?.role,
    camp = world.getComponent(target.id, COMPONENT.Camp)?.camp,
    state = role?.privateState;
  return {
    role,
    isCurrent: () =>
      livingNightLife(world, target) &&
      world.getComponent(target.id, COMPONENT.Role) === role &&
      role?.role === kind &&
      world.getComponent(target.id, COMPONENT.Camp)?.camp === camp &&
      role?.privateState === state,
  };
}
/** 仅已提交 Seer 类动作调用；只读／身份查验不提交狐狸致死关系。 */
export function commitFoxInspection(
  world: World,
  state: NightStageState,
  target: NightLifeScope,
  day: number,
  ownerCurrent: () => boolean,
): void {
  const identity = captureInspectionIdentity(world, target);
  if (identity.role?.role !== Role.CursedFox || world.getComponent(target.id, COMPONENT.Camp)?.camp !== Camp.ThirdParty) return;
  (state.foxInspections ??= []).push({
    target,
    isTargetCurrent: identity.isCurrent,
    isCurrent: () => ownerCurrent() && identity.isCurrent(),
  });
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

/**
 * 负责按原狼队权限执行夜聊轮次与刀票重试，捕获行动者与目标的原身体／生命版本。
 * 输入为原夜上下文、狼队资格和已校验工具；输出为夜聊、共识和带来源的刀口贡献。
 * 收票后由普通狼刀规则组合按原时点处理迷雾抽刀、映射和印记；贵族 God 刀口事实及必需记录归贵族发布 owner。
 * 原演员快照晚查实际阵营值，不增加 Camp 引用撤权；每个提交仍晚查现有狼队执行资格。
 * 不增加重试额度、重建已失效的身体或把发表事实当付款；首失败和已写前缀维持原边界。
 */
import { publishNobleNightKnife } from "../noble_secret_body/knife-ports";
import { isMistRavenBoard } from "../mist_raven/knife-ports";
import { resolveOrdinaryWolfKnife, type AcceptedWolfKnifeTarget } from "../../../../rulesets/ordinary-wolf-knife-routing";
import { nightmareKnifeBlocked } from "../nightmare_shadow/ports";
import { bindWolfKnifeTargetQuery } from "./ports";
/** 文件说明：狼人夜聊与刀人投票阶段处理。 */
import { EntityId, Phase } from "../../../../core/domain/model";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { NightStageHandler } from "../../stages/night/contracts";
import { wolfChatParticipants, wolfKnifeHolders, wolfTeamEvent } from "../wolf_team";
import { COMPONENT } from "../../../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { NightStageContext } from "../../stages/night/contracts";

const WOLF_DISCUSSION_MAX_ROUNDS = 3;
const WOLF_KILL_VOTE_MAX_RETRIES = 3;

/** 夜聊与刀票在原查询点读取具体板子的失败前缀，不缓存或改写首个错误。 */
function strictWolfFailurePrefix(ctx: NightStageContext): string | null {
  return ctx.nativeNightFailure.strictWolfFailurePrefix();
}

/** 捕获 Role、私有容器／顶层引用与原 Alive 版本；后续只复验同一身体，不复制或延长许可。 */
function captureActorScope(ctx: NightStageContext, actorId: EntityId): () => boolean {
  const role = ctx.world.getComponent(actorId, COMPONENT.Role),
    kind = role?.role,
    camp = ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp,
    state = role?.privateState,
    refs = state ? Object.entries(state) : [];
  const life = ctx.world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  return () =>
    ctx.isCurrent() &&
    !!role &&
    ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
    role.role === kind &&
    ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === camp &&
    role.privateState === state &&
    refs.every(([key, value]) => (state! as Readonly<Record<string, unknown>>)[key] === value) &&
    !!life &&
    ctx.world.getComponent(actorId, COMPONENT.Alive) === life &&
    life.alive &&
    version !== undefined &&
    aliveLifeVersion(life) === version;
}

const wolfDiscussionStage: NightStageHandler = {
  id: "wolf_discussion",
  priority: 200,
  async execute(ctx): Promise<void> {
    const wolfIds = ctx.shuffleWolves(wolfChatParticipants(ctx.world, ctx.roleCatalog));
    ctx.state.wolfChatOrder = wolfIds;
    ctx.state.endedWolves = new Set<EntityId>();

    if (wolfIds.length > 0) {
      ctx.events.push(
        wolfTeamEvent(ctx.world, ctx.roleCatalog, {
          timestamp: Date.now(),
          type: "wolf_tactical_order",
          payload: { order: [...wolfIds] },
        }),
      );
    }

    // 轮转夜聊：每只狼最多发言 WOLF_DISCUSSION_MAX_ROUNDS 次，end_chat 后跳过后续轮次。
    for (let round = 1; round <= WOLF_DISCUSSION_MAX_ROUNDS; round++) {
      for (const wolfId of wolfIds) {
        if (!wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId)) continue;
        if (ctx.state.endedWolves.has(wolfId)) {
          continue;
        }
        const actorCurrent = captureActorScope(ctx, wolfId);
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        const req = ctx.makeRequest(wolfId, ["speak_to_wolves"], {
          stage: "wolf_discussion",
          round,
          max_rounds: WOLF_DISCUSSION_MAX_ROUNDS,
        });
        const action = await ctx.actionProvider.getAction(req);
        if (!ctx.isCurrent()) return;
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        if (action?.name !== "speak_to_wolves") {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_missing`);
          continue;
        }

        if (
          strictWolfFailurePrefix(ctx) &&
          (typeof action.args?.text !== "string" || typeof action.args?.end_chat !== "boolean")
        ) {
          throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_invalid`);
        }
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, wolfId, action, {
          phase: req.phase,
        });
        if (!ctx.isCurrent()) return;
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        if (!result.ok || !result.sanitizedCall) {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_invalid`);
          continue;
        }
        if (result.sanitizedCall.args.end_chat) {
          ctx.state.endedWolves.add(wolfId);
          ctx.events.push(
            wolfTeamEvent(ctx.world, ctx.roleCatalog, {
              timestamp: Date.now(),
              type: "wolf_discussion_ended",
              payload: {
                actorId: wolfId,
                reason: result.sanitizedCall.args.text,
                round,
              },
            }),
          );
        } else {
          ctx.events.push(
            wolfTeamEvent(ctx.world, ctx.roleCatalog, {
              timestamp: Date.now(),
              type: "wolf_discussion",
              payload: {
                actorId: wolfId,
                text: result.sanitizedCall.args.text,
                endChat: false,
                round,
              },
            }),
          );
        }
      }
      if (ctx.state.endedWolves.size === wolfIds.length) {
        break;
      }
    }
  },
};

const wolfKillVoteStage: NightStageHandler = {
  id: "wolf_kill_vote",
  priority: 400,
  async execute(ctx): Promise<void> {
    ctx.state.wolfVotes = {};
    if (nightmareKnifeBlocked(ctx.world, ctx.currentDay())) {
      ctx.state.wolfTarget = null;
      delete ctx.state.wolfTargetScope;
      ctx.state.wolfTargetVoters = [];
      return;
    }
    const acceptedTargets: AcceptedWolfKnifeTarget[] = [];
    // 顺序收集狼刀票，统一在阶段末做多数决结算，避免中途状态污染。
    const knifeHolders = wolfKnifeHolders(ctx.world, ctx.roleCatalog);
    // 保留普通狼队原次序；仅有刀权的角色在后半名单独立加入。
    const voteOrder = [
      ...ctx.state.wolfChatOrder.filter((id) => knifeHolders.includes(id)),
      ...knifeHolders.filter((id) => !ctx.state.wolfChatOrder.includes(id)),
    ];
    const mistVoteScopes = isMistRavenBoard(ctx.world)
      ? new Map(voteOrder.map((id) => [id, captureActorScope(ctx, id)] as const))
      : null;
    const explicitPasses = new Set<EntityId>();
    for (const wolfId of voteOrder) {
      if (!wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      const actorCurrent = captureActorScope(ctx, wolfId);
      if (!actorCurrent()) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      let voteResolved: {
        abstain: boolean;
        targetId: EntityId | null;
        fallback: boolean;
        targetLife?: { life: AliveComponent; version: number };
      } | null = null;
      let retryReason = "";
      for (let attempt = 1; attempt <= WOLF_KILL_VOTE_MAX_RETRIES + 1; attempt++) {
        if (!actorCurrent()) break;
        if (!wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) break;
        const req =
          attempt === 1
            ? ctx.makeRequest(wolfId, ["kill_vote"], { stage: "wolf_vote" })
            : ctx.makeRequest(wolfId, ["kill_vote"], {
                stage: "wolf_vote",
                retry_attempt: attempt - 1,
                retry_max: WOLF_KILL_VOTE_MAX_RETRIES,
                retry_reason: retryReason,
                retry_notice_message: { key: "request.retry.wolf_vote" },
              });
        const targetLives = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
        );
        const action = await ctx.actionProvider.getAction(req);
        if (!ctx.isCurrent()) return;
        if (!actorCurrent()) break;
        if (action?.name !== "kill_vote") {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_missing`);
          retryReason = "no_valid_kill_vote_tool_call";
          if (attempt <= WOLF_KILL_VOTE_MAX_RETRIES) {
            safeRecordLogicOp({
              scope: "phase_pipeline",
              op: "wolf_kill_vote_retry_requested",
              actorId: wolfId,
              phase: Phase.Night,
              status: "fallback",
              reason: retryReason,
              output: {
                attempt,
                max_retries: WOLF_KILL_VOTE_MAX_RETRIES,
              },
            });
            continue;
          }
          break;
        }

        const result = ctx.toolGateway.validateAndSanitize(ctx.world, wolfId, action, {
          phase: Phase.Night,
        });
        if (!ctx.isCurrent()) return;
        if (!actorCurrent()) break;
        const target = result.sanitizedCall?.args.target_id,
          snapshot = typeof target === "number" ? targetLives.get(target) : undefined;
        const targetCurrent =
          result.sanitizedCall?.args.abstain === true ||
          target === null ||
          (!!snapshot &&
            bindWolfKnifeTargetQuery(ctx.world).allows(target as number) &&
            ctx.world.getComponent(target as number, COMPONENT.Alive) === snapshot.life &&
            snapshot.life.alive &&
            snapshot.version !== undefined &&
            aliveLifeVersion(snapshot.life) === snapshot.version);
        if (!result.ok || !result.sanitizedCall || !targetCurrent) {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_invalid`);
          retryReason = "invalid_kill_vote_arguments";
          if (attempt <= WOLF_KILL_VOTE_MAX_RETRIES) {
            safeRecordLogicOp({
              scope: "phase_pipeline",
              op: "wolf_kill_vote_retry_requested",
              actorId: wolfId,
              phase: Phase.Night,
              status: "fallback",
              reason: retryReason,
              output: {
                attempt,
                max_retries: WOLF_KILL_VOTE_MAX_RETRIES,
              },
            });
            continue;
          }
          break;
        }

        voteResolved = {
          abstain: result.sanitizedCall.args.abstain === true,
          targetId: result.sanitizedCall.args.target_id,
          fallback: attempt > 1,
          ...(!result.sanitizedCall.args.abstain && snapshot && snapshot.version !== undefined
            ? { targetLife: { life: snapshot.life, version: snapshot.version } }
            : {}),
        };
        break;
      }
      if (!actorCurrent() || !wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      if (!voteResolved) {
        if (strictWolfFailurePrefix(ctx))
          throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_missing`);
        voteResolved = {
          abstain: true,
          targetId: null,
          fallback: true,
        };
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "wolf_kill_vote_repaired_to_abstain",
          actorId: wolfId,
          phase: Phase.Night,
          status: "ok",
          reason: retryReason || "wolf_kill_vote_retry_exhausted",
          output: {
            fallback_abstain: true,
          },
        });
      }

      const abstain = voteResolved.abstain;
      const targetId = voteResolved.targetId;
      if (abstain && targetId === null) explicitPasses.add(wolfId);
      if (!abstain && targetId !== null) {
        if (voteResolved.targetLife)
          acceptedTargets.push({ actorId: wolfId, targetId, ...voteResolved.targetLife });
      }
      ctx.events.push(
        wolfTeamEvent(ctx.world, ctx.roleCatalog, {
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: {
            actorId: wolfId,
            abstain,
            targetId,
            ...(voteResolved.fallback ? { fallback: true } : {}),
          },
        }),
      );
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "wolf_kill_vote_cast",
        actorId: wolfId,
        phase: Phase.Night,
        status: "ok",
        output: { abstain, target_id: targetId },
      });
    }

    if (mistVoteScopes)
      for (const [id, current] of mistVoteScopes)
        if (!current() || !wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(id))
          throw new Error("mist_wolf_actor_stale");
    for (const target of acceptedTargets) {
      const current =
        ctx.world.getComponent(target.targetId, COMPONENT.Alive) === target.life &&
        target.life.alive &&
        aliveLifeVersion(target.life) === target.version &&
        bindWolfKnifeTargetQuery(ctx.world).allows(target.targetId);
      if (!current && mistVoteScopes) throw new Error("mist_wolf_target_stale");
      if (current)
        ctx.state.wolfVotes[target.targetId] = (ctx.state.wolfVotes[target.targetId] ?? 0) + 1;
    }
    const wolfTarget = resolveOrdinaryWolfKnife(ctx, acceptedTargets, voteOrder, explicitPasses);
    publishNobleNightKnife(() => ctx, wolfTarget);
  },
};

/** 狼人夜间阶段列表。 */
export const WOLF_NIGHT_STAGES: NightStageHandler[] = [wolfDiscussionStage, wolfKillVoteStage];

/**
 * 负责纯白之女与狼巫各自原生角色查验政策。
 * 输入为共享只读查询后的当前 actor、合法目标和验证行动；输出保留历史及既定攻击效果。
 * 三个状态读取与历史追加委托 RoleInspection 具体 writer，use 委托实例 owner，仍在原位置。
 * 目标阵营只晚查真实值；已付攻击保原 owner／target谓词，不添加动作墓碑或组件引用撤权。
 * 不合并阵营／角色查验、失败语义或阶段顺序，不引入最终目标复检。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { DeathCause } from "../../../../core/domain/deaths";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";

import { recordNightAbilityUse } from "../abilities";
import { captureNightAbilityScope } from "../ability_scope";
import { resolveInspection } from "../inspection";
import { ROLE_INSPECTION_STATE_SLOT } from "../role_inspection/ports";
import { recordRoleInspectionNightCommit } from "../role_inspection/night-commit-ports";
import { pureWhiteInspectionTargets } from "./rules";

async function execute(ctx: NightStageContext, policy: "pure_white" | "wolf_witch"): Promise<void> {
  const day = ctx.currentDay();
  const expectedRole = policy === "pure_white" ? Role.PureWhiteGirl : Role.WolfWitch;
  for (const { actorId, ability } of ctx.nightActors.actors("role_check", day)) {
    if (!ctx.isCurrent()) return;
    if (roleInspectionPolicy(ability.state) !== policy) continue;
    if (ability.source.kind !== "native" || ability.source.role !== expectedRole) continue;
    const scope = captureNightAbilityScope(
      ctx.world,
      actorId,
      ability,
      day,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    if (!scope || scope.role.role !== expectedRole) continue;
    const current = () => scope.isEligible() && roleInspectionPolicy(ability.state) === policy;
    const close = (reason: "passed" | "no_targets") => {
      if (!current()) return;
      recordNightAbilityUse(ability, day, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "role_inspection_skipped",
        payload: { actorId, day, reason },
      });
      // 跳过事实已按原点发表，随后才经轻端口登记本夜；发表失败不补登记或撤销先写的 use。
      recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
    };
    const targets = new Map(
      pureWhiteInspectionTargets(ctx.world, actorId, policy).map((id) => {
        const life = captureNightLife(ctx.world, id);
        const role = ctx.world.getComponent(id, COMPONENT.Role);
        return [id, { life, role, identity: role?.role, camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp }] as const;
      }),
    );
    if (!current()) continue;
    if (!targets.size) {
      close("no_targets");
      continue;
    }
    const request = ctx.makeRequest(actorId, ["inspect_night_identity"], {
      stage: policy === "pure_white" ? "pure_white_girl" : "wolf_witch",
      requiresAction: true,
      ability_id: ability.id,
      action_failure_policy: "error",
      allow_fallback: false,
    });
    const action = await ctx.actionProvider.getAction(request);
    if (!current()) continue;
    if (action?.name !== "inspect_night_identity")
      throw new Error("pure_white_inspection_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
      abilityId: ability.id,
    });
    if (!current()) continue;
    if (!validated.ok || validated.sanitizedCall?.name !== "inspect_night_identity")
      throw new Error("pure_white_inspection_action_invalid");
    const args = validated.sanitizedCall.args;
    if (args.abstain && args.target_id === null) {
      close("passed");
      continue;
    }
    const targetId = args.target_id;
    if (targetId === null) throw new Error("pure_white_inspection_target_invalid");
    const target = targets.get(targetId);
    const targetCurrent = () =>
      !!target?.life &&
      !!target.role &&
      livingNightLife(ctx.world, target.life) &&
      ctx.world.getComponent(targetId, COMPONENT.Role) === target.role &&
      target.role.role === target.identity &&
      ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp === target.camp &&
      pureWhiteInspectionTargets(ctx.world, actorId, policy).includes(targetId);
    if (!targetCurrent()) throw new Error("pure_white_inspection_target_stale");
    const result = resolveInspection(ctx.world, targetId, "role", ctx.roleCatalog);
    if (!current()) continue;
    if (!result || !targetCurrent()) throw new Error("pure_white_inspection_target_stale");
    ROLE_INSPECTION_STATE_SLOT.allowedWrites.appendAbility(ability, targetId, day, result);
    recordNightAbilityUse(ability, day, true);
    ctx.events.push({
      timestamp: Date.now(),
      type: "role_inspected",
      payload: { actorId, targetId, day, result: { ...result } },
    });
    recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
    if (
      day >= 2 &&
      (policy === "pure_white"
        ? target!.camp === Camp.Wolf
        : target!.identity === Role.PureWhiteGirl)
    ) {
      (ctx.state.inspectionAttacks ??= []).push({
        actorId,
        target: target!.life!,
        cause:
          policy === "pure_white" ? DeathCause.PureWhiteInspection : DeathCause.WolfWitchInspection,
        isCurrent: () =>
          scope.isOwnerCurrent() &&
          !ability.disabled &&
          !ability.deathExpired &&
          targetCurrent() &&
          roleInspectionPolicy(ability.state) === policy,
      });
    }
  }
}
export const PURE_WHITE_INSPECTION_STAGE: NightStageHandler = {
  id: "pure_white_inspection",
  priority: 610,
  execute: (ctx) => execute(ctx, "pure_white"),
};
export const WOLF_WITCH_INSPECTION_STAGE: NightStageHandler = {
  id: "wolf_witch_inspection",
  priority: 620,
  execute: (ctx) => execute(ctx, "wolf_witch"),
};

/**
 * 负责觉醒隐狼的工具资格校验贡献。输入为原工具参数、角色状态及可信窗口，输出原规则拒绝或通过。
 * 当前原体、学习／盾／刀资格仍归实际机制，本校验不执行学习、消费库存或提交死亡。
 */
import { AWAKENED_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { isAliveTarget, type ToolRule, type ToolRuleMap } from "../../validation/contracts";
import { canAwakenedKnife } from "./inheritance";
import { currentAwakenedNight } from "./night_scope";
import {
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  getAwakenedState,
} from "./state";

const validateAwakened: ToolRule = ({ world, actorId, role, phase, day, toolCall }) => {
  const state = getAwakenedState(role);
  if (
    role.role !== Role.AwakenedHiddenWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    day === undefined ||
    currentAwakenedNight(world, role) !== day
  )
    return { code: RuleError.AwakenedUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "awakened_mimic") {
    if (!canAwakenedMimic(state, day)) return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  const skill = awakenedSkillForNight(state, day);
  if (toolCall.name === "awakened_attack") {
    if (!canAwakenedKnife(role, world, () => world.getComponent(actorId, COMPONENT.Camp)) || !canAwakenedExtraKnife(state, day))
      return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  if (toolCall.name === "awakened_poison" && skill?.kind === "poison")
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  if (toolCall.name === "awakened_guard" && skill?.kind === "guard") {
    if (toolCall.args.target_id !== null && !isAliveTarget(world, toolCall.args.target_id))
      return { code: RuleError.AwakenedTarget };
    if (
      toolCall.args.target_id !== null &&
      skill.lastTarget === toolCall.args.target_id &&
      skill.lastGuardDay === day - 1
    )
      return { code: RuleError.AwakenedGuardRepeat };
    return null;
  }
  return { code: RuleError.AwakenedUnavailable };
};
export { AWAKENED_TOOL_NAMES } from "./tool_names";
export const AWAKENED_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  AWAKENED_TOOL_NAMES.map((name) => [name, validateAwakened]),
);

/**
 * 负责机械狼工具的本夜模式与行动资格校验。输入为原工具参数、角色状态及可信上下文，输出原规则拒绝或通过。
 * 预检不等于复制、付款或落效果，原体与能力资源仍由机械机制持有并在提交时复验。
 */
import { MECHANICAL_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { ToolRule, ToolRuleMap } from "../../validation/contracts";
import { isAliveTarget } from "../../validation/contracts";
import { canMechanicalKnife } from "./inheritance";
import { hasCurrentMechanicalMode } from "./night_scope";
import {
  canMechanicalMimic,
  canSelectMechanicalMode,
  canMechanicalExtraKnife,
  getMechanicalState,
  mechanicalSkillForNight,
} from "./state";

const validateMechanical: ToolRule = ({ world, actorId, role, day, phase, toolCall }) => {
  const state = getMechanicalState(role);
  if (role.role !== Role.MechanicalWolf || world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf || !state || day === undefined)
    return { code: RuleError.MechanicalUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "mechanical_mode") {
    return canSelectMechanicalMode(state, day) && ["kill", "skill"].includes(toolCall.args.mode)
      ? null
      : { code: RuleError.MechanicalUnavailable };
  }
  if (toolCall.name === "mimic_role") {
    if (!canMechanicalMimic(state, day)) return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_attack") {
    if (!canMechanicalKnife(role, world, () => world.getComponent(actorId, COMPONENT.Camp)) || !canMechanicalExtraKnife(state, day))
      return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  const skill = hasCurrentMechanicalMode(world, role, "skill")
    ? mechanicalSkillForNight(state, day)
    : undefined;
  if (toolCall.name === "mechanical_inspect" && skill?.kind === "inspection") {
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_poison" && skill?.kind === "poison" && skill.remaining > 0) {
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_guard" && skill?.kind === "guard") {
    // 连续守护同编号仍是合法提交；惩罚在黎明生效，不能在预检阶段代付或拒绝。
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  return { code: RuleError.MechanicalUnavailable };
};

export { MECHANICAL_TOOL_NAMES } from "./tool_names";
export const MECHANICAL_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  MECHANICAL_TOOL_NAMES.map((name) => [name, validateMechanical]),
);

/**
 * 负责 丘比特 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { CUPID_POLICIES } from "../../../../core/domain/board";
