    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("cupid"),
    skillBrief: text("zh-CN", "role.cupid.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Cupid,
      Role.Wolf,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Knight,
      Role.Dreamer,
      Role.WolfBeauty,
    ],
  },
  runtime: {
