    configuration: {
      schema: parameters,
      defaults: { policy: "netease_2017_cupid_follows_lovers_v1" },
      apply: (config, value) => ({ ...config, cupid: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.cupid ?? {}),
    },
    nightStages: [CUPID_STAGE],
    toolSpecs: [
      {
        name: "choose_lovers",
        parameters: {
